package edu.dbms.portfolio;

import edu.dbms.portfolio.config.*;
import edu.dbms.portfolio.dao.*;
import edu.dbms.portfolio.model.*;
import edu.dbms.portfolio.service.TransactionService;
import edu.dbms.portfolio.service.Validation;
import edu.dbms.portfolio.util.Money;
import javafx.application.Application;
import javafx.beans.property.SimpleStringProperty;
import javafx.collections.FXCollections;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.chart.*;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Stage;
import java.math.BigDecimal;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.List;

/** JavaFX entry point. The demo user is the seeded USERS row with id 1. */
public final class PortfolioApplication extends Application {
    private static final long DEMO_USER_ID=1L;
    private final DatabaseConfig config=DatabaseConfig.load();
    private final ConnectionFactory connectionFactory=new ConnectionFactory(config);
    private final PortfolioDao portfolios=new PortfolioDao(connectionFactory);
    private final MarketDao market=new MarketDao(connectionFactory);
    private final TransactionService transactions=new TransactionService(connectionFactory);
    private BorderPane root; private StackPane content; private Label status;
    @Override public void start(Stage stage) {
        root=new BorderPane(); root.getStyleClass().add("app-root"); content=new StackPane(); content.getStyleClass().add("workspace");
        root.setLeft(sidebar()); root.setCenter(content); root.setBottom(statusBar()); showDashboard();
        Scene scene=new Scene(root,1280,780); scene.getStylesheets().add(getClass().getResource("/css/app.css").toExternalForm()); stage.setTitle("Portfolio Management Database System"); stage.setMinWidth(1000);stage.setMinHeight(650);stage.setScene(scene);stage.show();
    }
    private VBox sidebar(){ VBox side=new VBox(8);side.getStyleClass().add("sidebar"); Label brand=new Label("PORTFOLIO\nMANAGER");brand.getStyleClass().add("brand"); Label sub=new Label("DBMS Lab · Phase II");sub.getStyleClass().add("sidebar-subtitle");side.getChildren().addAll(brand,sub,new Separator()); String[] names={"Dashboard","Portfolios","Stock Explorer","Buy / Sell","Holdings","Watchlist","Transactions","Price History","Analytics","About","Settings"}; for(String name:names){Button b=new Button(name);b.getStyleClass().add("nav-button");b.setMaxWidth(Double.MAX_VALUE);b.setOnAction(e->navigate(name));side.getChildren().add(b);} VBox.setVgrow(new Region(),Priority.ALWAYS); Label footer=new Label("Version 1.0\nOracle-backed mode");footer.getStyleClass().add("sidebar-subtitle");side.getChildren().add(footer);return side;}
    private HBox statusBar(){status=new Label("Checking Oracle configuration…");status.getStyleClass().add("status");HBox bar=new HBox(status);bar.getStyleClass().add("status-bar");return bar;}
    private void navigate(String page){switch(page){case "Dashboard"->showDashboard();case "Portfolios"->showPortfolios();case "Stock Explorer"->showStocks();case "Buy / Sell"->showTransactionForm();case "Holdings"->showHoldings();case "Watchlist"->showWatchlist();case "Transactions"->showTransactions();case "Price History"->showPrices();case "Analytics"->showAnalytics();case "About"->showAbout();case "Settings"->showSettings();default->showError("Unknown view.");}}
    private void setPage(String title,String detail, javafx.scene.Node body){VBox page=new VBox(20);page.setPadding(new Insets(30));Label h=new Label(title);h.getStyleClass().add("page-title");Label d=new Label(detail);d.getStyleClass().add("page-detail");page.getChildren().addAll(h,d,body);content.getChildren().setAll(page);}
    private VBox card(String label,String value,String extra){VBox box=new VBox(7);box.getStyleClass().add("metric-card");Label l=new Label(label);l.getStyleClass().add("metric-label");Label v=new Label(value);v.getStyleClass().add("metric-value");Label e=new Label(extra);e.getStyleClass().add("metric-extra");box.getChildren().addAll(l,v,e);return box;}
    private void showDashboard(){try{List<Portfolio> all=portfolios.listForUser(DEMO_USER_ID);BigDecimal invested=all.stream().map(Portfolio::invested).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal value=all.stream().map(Portfolio::marketValue).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal pl=value.subtract(invested);double ret=invested.signum()==0?0:pl.multiply(BigDecimal.valueOf(100)).divide(invested,2,java.math.RoundingMode.HALF_UP).doubleValue();HBox metrics=new HBox(14,card("TOTAL MARKET VALUE",Money.format(value),"Stored prices"),card("INVESTED AMOUNT",Money.format(invested),"Open cost basis"),card("UNREALISED P/L",Money.format(pl),String.format("%.2f%% return",ret)),card("PORTFOLIOS",String.valueOf(all.size()),"Demo user"));metrics.setFillHeight(true);Button quick=new Button("Record a transaction");quick.getStyleClass().add("primary-button");quick.setOnAction(e->showTransactionForm());VBox body=new VBox(22,metrics,section("Portfolio overview",portfolioTable(all)),section("Quick action",quick));setPage("Good morning, Pranav","All figures are calculated from your Oracle transaction ledger and latest stored prices.",body);setStatus("Dashboard loaded from Oracle.");}catch(SQLException ex){setPage("Portfolio dashboard","The application does not fabricate figures while Oracle is unavailable.",emptyState("Database unavailable",friendly(ex)));setStatus("Oracle not connected — configure Settings and retry.");}}
    private VBox section(String title, javafx.scene.Node node){VBox s=new VBox(10);Label l=new Label(title);l.getStyleClass().add("section-title");s.getChildren().addAll(l,node);return s;}
    private TableView<Portfolio> portfolioTable(List<Portfolio> rows){TableView<Portfolio> t=new TableView<>(FXCollections.observableArrayList(rows));t.getColumns().addAll(column("Portfolio",x->x.name()),column("Description",x->x.description()),column("Invested",x->Money.format(x.invested())),column("Market value",x->Money.format(x.marketValue())),column("Unrealised P/L",x->Money.format(x.unrealizedPl())));t.setPlaceholder(new Label("No portfolios yet. Create one to begin."));t.setPrefHeight(230);return t;}
    private <T> TableColumn<T,String> column(String text,java.util.function.Function<T,String> fn){TableColumn<T,String> c=new TableColumn<>(text);c.setCellValueFactory(v->new SimpleStringProperty(String.valueOf(fn.apply(v.getValue()))));c.setPrefWidth(170);return c;}
    private void showPortfolios(){try{List<Portfolio> all=portfolios.listForUser(DEMO_USER_ID);TextField name=new TextField();name.setPromptText("Portfolio name");TextField description=new TextField();description.setPromptText("Short description (optional)");Button create=new Button("Create portfolio");create.getStyleClass().add("primary-button");create.setOnAction(e->{try{portfolios.create(DEMO_USER_ID,Validation.required(name.getText(),"Portfolio name"),description.getText());showPortfolios();setStatus("Portfolio created.");}catch(Exception x){showError(friendly(x));}});HBox form=new HBox(10,name,description,create);setPage("Portfolios","Create, view, and manage distinct investment portfolios.",new VBox(20,form,portfolioTable(all)));}catch(SQLException ex){setPage("Portfolios","Oracle data is required for portfolio management.",emptyState("Unable to load portfolios",friendly(ex)));}}
    private void showStocks(){TextField search=new TextField();search.setPromptText("Search symbol or company");ComboBox<String> sector=new ComboBox<>();sector.getItems().addAll("","Banking","Information Technology","Energy","Consumer Goods","Pharmaceuticals");sector.setPromptText("All sectors");TableView<Stock> table=new TableView<>();table.getColumns().addAll(column("Symbol",Stock::symbol),column("Company",Stock::companyName),column("Sector",Stock::sector),column("Exchange",Stock::exchange),column("Latest stored price",x->Money.format(x.price())),column("Price date",x->String.valueOf(x.priceDate())));Button load=new Button("Search");load.getStyleClass().add("primary-button");load.setOnAction(e->{try{table.setItems(FXCollections.observableArrayList(market.stocks(search.getText(),sector.getValue())));setStatus("Stock directory refreshed.");}catch(SQLException x){showError(friendly(x));}});setPage("Stock Explorer","Prices are seeded demonstration records, not live market data.",new VBox(18,new HBox(10,search,sector,load),table));load.fire();}
    private void showTransactionForm(){try{List<Portfolio> ps=portfolios.listForUser(DEMO_USER_ID);List<Stock> ss=market.stocks("",null);ComboBox<Portfolio> p=new ComboBox<>(FXCollections.observableArrayList(ps));p.setPromptText("Portfolio");p.setCellFactory(v->new ListCell<>(){protected void updateItem(Portfolio a,boolean e){super.updateItem(a,e);setText(e||a==null?null:a.name());}});p.setButtonCell(new ListCell<>(){protected void updateItem(Portfolio a,boolean e){super.updateItem(a,e);setText(e||a==null?null:a.name());}});ComboBox<Stock> s=new ComboBox<>(FXCollections.observableArrayList(ss));s.setPromptText("Stock");s.setCellFactory(v->new ListCell<>(){protected void updateItem(Stock a,boolean e){super.updateItem(a,e);setText(e||a==null?null:a.symbol()+" — "+a.companyName());}});s.setButtonCell(new ListCell<>(){protected void updateItem(Stock a,boolean e){super.updateItem(a,e);setText(e||a==null?null:a.symbol());}});ComboBox<TransactionType> type=new ComboBox<>(FXCollections.observableArrayList(TransactionType.values()));type.setValue(TransactionType.BUY);TextField qty=new TextField();qty.setPromptText("Quantity");TextField price=new TextField();price.setPromptText("Execution price");TextField fees=new TextField("0");DatePicker date=new DatePicker(LocalDate.now());TextArea notes=new TextArea();notes.setPromptText("Notes (optional)");notes.setPrefRowCount(3);Button submit=new Button("Review & submit");submit.getStyleClass().add("primary-button");submit.setOnAction(e->{try{if(p.getValue()==null||s.getValue()==null)throw new IllegalArgumentException("Choose a portfolio and stock.");BigDecimal q=new BigDecimal(qty.getText().trim());BigDecimal pr=new BigDecimal(price.getText().trim());BigDecimal f=new BigDecimal(fees.getText().trim());Alert confirm=new Alert(Alert.AlertType.CONFIRMATION,"Record "+type.getValue()+" of "+q+" "+s.getValue().symbol()+" at "+Money.format(pr)+"?",ButtonType.OK,ButtonType.CANCEL);confirm.setHeaderText("Confirm transaction");if(confirm.showAndWait().orElse(ButtonType.CANCEL)!=ButtonType.OK)return;transactions.submit(p.getValue().id(),s.getValue().id(),type.getValue(),q,pr,date.getValue(),f,notes.getText());setStatus("Transaction committed in Oracle.");showDashboard();}catch(Exception x){showError(friendly(x));}});GridPane g=formGrid();add(g,"Portfolio",p,0);add(g,"Stock",s,1);add(g,"Type",type,2);add(g,"Quantity",qty,3);add(g,"Execution price",price,4);add(g,"Fees",fees,5);add(g,"Trade date",date,6);add(g,"Notes",notes,7);g.add(submit,1,8);setPage("Buy / Sell","Submissions call ADD_BUY_TRANSACTION or ADD_SELL_TRANSACTION. Oversells are rejected by Oracle.",g);}catch(SQLException ex){setPage("Buy / Sell","Transactions require the Oracle schema and seed data.",emptyState("Cannot load transaction form",friendly(ex)));}}
    private GridPane formGrid(){GridPane g=new GridPane();g.setHgap(15);g.setVgap(12);g.getStyleClass().add("form-grid");return g;}private void add(GridPane g,String label,javafx.scene.Node node,int row){g.add(new Label(label),0,row);g.add(node,1,row);GridPane.setHgrow(node,Priority.ALWAYS);}
    private void showHoldings(){try{List<Portfolio> all=portfolios.listForUser(DEMO_USER_ID);ComboBox<Portfolio> pick=new ComboBox<>(FXCollections.observableArrayList(all));pick.setPromptText("Choose a portfolio");TableView<Holding> table=new TableView<>();table.getColumns().addAll(column("Symbol",Holding::symbol),column("Company",Holding::company),column("Quantity",x->x.quantity().stripTrailingZeros().toPlainString()),column("Average cost",x->Money.format(x.averageCost())),column("Cost basis",x->Money.format(x.costBasis())),column("Market value",x->Money.format(x.marketValue())),column("Unrealised P/L",x->Money.format(x.unrealizedPl())));Button show=new Button("View holdings");show.setOnAction(e->{try{if(pick.getValue()==null)throw new IllegalArgumentException("Choose a portfolio.");table.setItems(FXCollections.observableArrayList(market.holdings(pick.getValue().id())));}catch(Exception x){showError(friendly(x));}});setPage("Holdings","Average cost uses weighted-average cost; closed positions are not displayed.",new VBox(18,new HBox(10,pick,show),table));}catch(SQLException ex){setPage("Holdings","Current positions derive from the ledger-maintained HOLDINGS table.",emptyState("Cannot load holdings",friendly(ex)));}}
    private void showWatchlist(){try{List<Stock> stocks=market.stocks("",null);ComboBox<Stock> pick=new ComboBox<>(FXCollections.observableArrayList(stocks));pick.setPromptText("Choose a stock to add");pick.setCellFactory(v->new ListCell<>(){protected void updateItem(Stock a,boolean e){super.updateItem(a,e);setText(e||a==null?null:a.symbol()+" — "+a.companyName());}});pick.setButtonCell(new ListCell<>(){protected void updateItem(Stock a,boolean e){super.updateItem(a,e);setText(e||a==null?null:a.symbol());}});TableView<Stock> table=new TableView<>(FXCollections.observableArrayList(market.watchlist(DEMO_USER_ID)));table.getColumns().addAll(column("Symbol",Stock::symbol),column("Company",Stock::companyName),column("Sector",Stock::sector),column("Latest stored price",x->Money.format(x.price())));Button add=new Button("Add to watchlist");add.getStyleClass().add("primary-button");add.setOnAction(e->{try{if(pick.getValue()==null)throw new IllegalArgumentException("Choose a stock.");market.addWatchlist(DEMO_USER_ID,pick.getValue().id());showWatchlist();setStatus(pick.getValue().symbol()+" added to watchlist.");}catch(Exception x){showError(friendly(x));}});Button remove=new Button("Remove selected");remove.setOnAction(e->{try{if(table.getSelectionModel().getSelectedItem()==null)throw new IllegalArgumentException("Select a watchlist row.");market.removeWatchlist(DEMO_USER_ID,table.getSelectionModel().getSelectedItem().id());showWatchlist();}catch(Exception x){showError(friendly(x));}});setPage("Watchlist","Duplicate user-and-stock pairs are prevented by an Oracle unique constraint.",new VBox(18,new HBox(10,pick,add,remove),table));}catch(SQLException ex){setPage("Watchlist","Your watchlist is stored in Oracle.",emptyState("Cannot load stocks",friendly(ex)));}}
    private void showTransactions(){try{TableView<LedgerRow> t=new TableView<>(FXCollections.observableArrayList(market.transactions(DEMO_USER_ID)));t.getColumns().addAll(column("Date",x->String.valueOf(x.date())),column("Portfolio",LedgerRow::portfolio),column("Stock",LedgerRow::symbol),column("Type",x->x.type().name()),column("Quantity",x->x.quantity().stripTrailingZeros().toPlainString()),column("Price",x->Money.format(x.price())),column("Fees",x->Money.format(x.fees())),column("Realised P/L",x->Money.format(x.realisedPl())));setPage("Transaction History","The immutable ledger is the source of truth; corrections should be recorded as reversals.",t);}catch(SQLException ex){setPage("Transaction History","Filterable ledger data requires Oracle.",emptyState("Cannot load transaction history",friendly(ex)));}}
    private void showPrices(){try{TextField symbol=new TextField();symbol.setPromptText("Optional exact symbol, e.g. TCS");TableView<PriceRecord> t=new TableView<>();t.getColumns().addAll(column("Symbol",PriceRecord::symbol),column("Price date",x->String.valueOf(x.date())),column("Close price",x->Money.format(x.closePrice())),column("Source",PriceRecord::source));Button load=new Button("Load prices");load.setOnAction(e->{try{t.setItems(FXCollections.observableArrayList(market.prices(symbol.getText().trim())));}catch(SQLException x){showError(friendly(x));}});setPage("Historical Prices","Stored seeded records are demonstrative, not a live market feed.",new VBox(18,new HBox(10,symbol,load),t));load.fire();}catch(Exception ex){setPage("Historical Prices","Oracle price history data is unavailable.",emptyState("Cannot load prices",friendly(ex)));}}
    private void showAnalytics(){try{List<Portfolio> ps=portfolios.listForUser(DEMO_USER_ID);CategoryAxis x=new CategoryAxis();NumberAxis y=new NumberAxis();BarChart<String,Number> chart=new BarChart<>(x,y);chart.setTitle("Current market value by portfolio");chart.setLegendVisible(false);XYChart.Series<String,Number> series=new XYChart.Series<>();for(Portfolio p:ps)series.getData().add(new XYChart.Data<>(p.name(),p.marketValue()));chart.getData().add(series);setPage("Analytics & Reports","Values use current holdings and latest stored prices. Further Oracle reports are in sql/09_demo_queries.sql.",new VBox(14,chart,portfolioTable(ps)));}catch(SQLException ex){setPage("Analytics & Reports","Oracle analytics cannot be calculated without a connection.",emptyState("Cannot load analytics",friendly(ex)));}}
    private void showAbout(){Label text=new Label("Portfolio Management Database System\n\nA database-driven DBMS Lab Mini Project for managing portfolios, stock master data, watchlists, transaction history, holdings, historical prices, and analytics.\n\nTeam: Pranav Suryadevara (251090580090), Sanvi Kulkarni (251090580001), Erwin Clint Olivera (251090580002).\n\nTechnology: Java 17, JavaFX, Maven, Oracle Database, JDBC, SQL and PL/SQL.\n\nLimitations: seeded prices are educational demonstration data, not live quotes. The interface is intentionally single-user for the lab while the schema retains user ownership.\n\nVersion 1.0 · DBMS Lab Mini Project · Phase II");text.setWrapText(true);setPage("About this project","Purpose, implementation boundaries, and academic context.",text);}
    private void showSettings(){Label endpoint=new Label("Configured endpoint: "+(config.url().isBlank()?"Not configured":config.safeEndpoint()));Button test=new Button("Test Oracle connection");test.getStyleClass().add("primary-button");test.setOnAction(e->{try{connectionFactory.testConnection();setStatus("Connection successful.");showInfo("Oracle connection succeeded.");}catch(SQLException x){setStatus("Connection failed.");showError(friendly(x));}});setPage("Settings & database status","Credentials are loaded from environment variables or an ignored .env file and never displayed.",new VBox(16,endpoint,test,new Label("Required variables: ORACLE_JDBC_URL, ORACLE_DB_USER, ORACLE_DB_PASSWORD\nSee .env.example and README.md for setup.")));}
    private VBox emptyState(String title,String message){VBox b=new VBox(10);b.getStyleClass().add("empty-state");Label t=new Label(title);t.getStyleClass().add("section-title");Label m=new Label(message);m.setWrapText(true);b.getChildren().addAll(t,m);return b;}
    private void setStatus(String value){status.setText(value);} private void showError(String message){Alert a=new Alert(Alert.AlertType.ERROR,message,ButtonType.OK);a.setHeaderText("Action could not be completed");a.show();}private void showInfo(String message){Alert a=new Alert(Alert.AlertType.INFORMATION,message,ButtonType.OK);a.setHeaderText("Portfolio Manager");a.show();}private String friendly(Exception x){String m=x.getMessage();return m==null?"An unexpected database error occurred.":m.replaceAll("(?i)password[^ ]*","credential");}
}
